-- GROUP 08: SCHOLARSHIP APPLICATION MANAGEMENT
-- Revised 29 October 2026: no CHECK clauses; no standalone KEY/INDEX declarations.
-- PRIMARY KEY, FOREIGN KEY and UNIQUE definitions are retained.
-- The named student/offering uniqueness rule uses CONSTRAINT ... UNIQUE, not
-- UNIQUE KEY syntax. No CREATE INDEX or ALTER TABLE ADD INDEX workaround is used.
-- G08_scholapp; MySQL 8.0.16+ / InnoDB / strict SQL mode.
-- Two years of actual simulated activity: 2024-2025; snapshot 2025-12-31.
-- Refined schema adds COLLEGE, AGENCY, PROGRAM_TYPE, PROGRAM_DOCUMENT, and subtype tables; original activity preserved.
-- All identities, program offerings, criteria, documents, and decisions simulated.
-- Agency names do not make these official CHED/DOST/DA/DOH programs or policies.
-- example.org contacts; NULL mobile values; no real documents or credentials.
-- GPA 1.00-5.00 with LOWER better; compare gpa <= maxgpa. Scores/entry averages
-- use the separate 0-100 scale. Previous awards are external, not Group 06 FKs.
-- Planned intake/coverage may extend to 2026; no actual activity extends there.
-- PR008 is currently inactive; earlier offerings and valid actions are retained.
-- Current saved states/results are not a full historical event or policy trail.
-- Reference and subtype tables are included in this refined schema.
-- College/agency descriptions remain repeated for student 3NF restructuring.
-- Fresh creation only; not migration. No DROP. Stop on the first error; no --force.
-- Existing tables cause errors. MySQL DDL is not transactional; seed INSERTs are.
-- No explicit character-set declarations. No triggers/routines replace omissions.
--
-- REPORTS: R1/R2 preserve zero-activity parent records; R3 uses evaldate with
-- actual saved scores; R4 uses document receipt date and CURRENT result.
-- Do not combine independent document/check branches to inflate application counts.
-- Zero is a real score; NULL means no saved evaluation. Default period is 2025.

SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
CREATE DATABASE IF NOT EXISTS G08_scholapp;
USE G08_scholapp;

CREATE TABLE college (
 collcode VARCHAR(8) NOT NULL PRIMARY KEY,
 collname VARCHAR(100) NOT NULL
) ENGINE=InnoDB;


CREATE TABLE applicant (
 studno VARCHAR(12) NOT NULL PRIMARY KEY,
 fullname VARCHAR(100) NOT NULL,
 email VARCHAR(120) NOT NULL,
 mobile VARCHAR(24) NULL,
 regdate DATE NOT NULL,
 collcode VARCHAR(8) NOT NULL,
 course VARCHAR(100) NOT NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (collcode) REFERENCES college(collcode)
    ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE program_type (
 progtype VARCHAR(20) NOT NULL PRIMARY KEY
) ENGINE=InnoDB;

VALUES ('FirstAward'), ('Renewal');

CREATE TABLE agency (
 agencode VARCHAR(8) NOT NULL PRIMARY KEY,
 agenname VARCHAR(120) NOT NULL
) ENGINE=InnoDB;


CREATE TABLE program (
 progcode VARCHAR(12) NOT NULL PRIMARY KEY,
 progname VARCHAR(120) NOT NULL,
 agencode VARCHAR(8) NOT NULL,
 progtype VARCHAR(20) NOT NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (agencode) REFERENCES agency(agencode)
    ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY (progtype) REFERENCES program_type(progtype)
    ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE program_document (
 progtype VARCHAR(20) NOT NULL,
 doctype VARCHAR(20) NOT NULL,
 PRIMARY KEY (progtype, doctype),
 FOREIGN KEY (progtype) REFERENCES program_type(progtype)
) ENGINE=InnoDB;


CREATE TABLE first_award_program (
 progcode VARCHAR(12) NOT NULL PRIMARY KEY,
 entrymin DECIMAL(5,2) NOT NULL,
 incomecp DECIMAL(12,2) NOT NULL,
 FOREIGN KEY (progcode) REFERENCES program(progcode)
    ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE renewal_program (
 progcode VARCHAR(12) NOT NULL PRIMARY KEY,
 minunits SMALLINT UNSIGNED NOT NULL,
 maxgpa DECIMAL(4,2) NOT NULL,
 FOREIGN KEY (progcode) REFERENCES program(progcode)
    ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE program (
 progcode VARCHAR(12) NOT NULL PRIMARY KEY,
 progname VARCHAR(120) NOT NULL,
 agencode VARCHAR(8) NOT NULL,
 agenname VARCHAR(120) NOT NULL,
 progtype ENUM('FirstAward','Renewal') NOT NULL,
 entrymin DECIMAL(5,2) NULL,
 incomecp DECIMAL(12,2) NULL,
 minunits SMALLINT UNSIGNED NULL,
 maxgpa DECIMAL(4,2) NULL,
 active TINYINT UNSIGNED NOT NULL DEFAULT 1,
 revno INT UNSIGNED NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE offering (
 offerno VARCHAR(16) NOT NULL PRIMARY KEY,
 progcode VARCHAR(12) NOT NULL,
 title VARCHAR(120) NOT NULL,
 opendt DATE NOT NULL,
 closedt DATE NOT NULL,
 coverst DATE NOT NULL,
 coverend DATE NOT NULL,
 slots SMALLINT UNSIGNED NOT NULL,
 status ENUM('Planned','Open','Closed','Cancelled') NOT NULL DEFAULT 'Planned',
 remarks VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (progcode) REFERENCES program(progcode)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE application (
 appno VARCHAR(16) NOT NULL PRIMARY KEY,
 studno VARCHAR(12) NOT NULL,
 offerno VARCHAR(16) NOT NULL,
 submitdt DATE NOT NULL,
 entryavg DECIMAL(5,2) NULL,
 income DECIMAL(12,2) NULL,
 score DECIMAL(5,2) NULL,
 evaldate DATE NULL,
 evalby VARCHAR(100) NULL,
 status ENUM('Submitted','Evaluated','Approved','Rejected','Withdrawn')
   NOT NULL DEFAULT 'Submitted',
 decdate DATE NULL,
 remarks VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 CONSTRAINT uq_student_offer UNIQUE (studno,offerno),
 FOREIGN KEY (studno) REFERENCES applicant(studno)
   ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY (offerno) REFERENCES offering(offerno)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE document (
 appno VARCHAR(16) NOT NULL,
 doctype ENUM('Identity','Grades','Income','Enrollment') NOT NULL,
 recvdate DATE NOT NULL,
 docref VARCHAR(40) NOT NULL,
 result ENUM('Pending','Accepted','Rejected') NOT NULL DEFAULT 'Pending',
 verdate DATE NULL,
 verifyby VARCHAR(100) NULL,
 notes VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 PRIMARY KEY (appno,doctype),
 FOREIGN KEY (appno) REFERENCES application(appno)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE renewcheck (
 checkno VARCHAR(16) NOT NULL PRIMARY KEY,
 appno VARCHAR(16) NOT NULL UNIQUE,
 awardref VARCHAR(40) NOT NULL,
 units SMALLINT UNSIGNED NOT NULL,
 gpa DECIMAL(4,2) NOT NULL,
 checkdt DATE NOT NULL,
 checkby VARCHAR(100) NOT NULL,
 result ENUM('Eligible','Ineligible') NOT NULL,
 notes VARCHAR(255) NULL,
 revno INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (appno) REFERENCES application(appno)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

-- AUTHORITATIVE APPLICATION VALIDATION (not fully enforced by this DDL):
-- Required text is nonblank, active is 0/1, revno >= 1; validate ranges and dates.
-- FirstAward program requires entrymin 0-100/incomecp >= 0 with renewal fields
-- NULL; Renewal requires minunits>0/maxgpa 1-5 with initial fields NULL.
-- Offering windows/coverage ordered; slots>0; cancellation explained. New
-- offerings require an active program; preserve existing ones after inactivation.
-- New submission: Open offering, inclusive dates, registration<=submission,
-- no future actual dates. FirstAward requires entryavg 0-100 and income>=0;
-- Renewal leaves both NULL. One student/one offering also has a UNIQUE constraint.
-- A score/evaluation date/evaluator are one coherent record: score 0-100,
-- evaluation>=submission. Submitted has no evaluation; Evaluated/Approved require
-- it. Final states require decision date >= submission/evaluation; nonfinal
-- states leave it NULL. Rejected/Withdrawn require meaningful explanations.
-- FirstAward document categories: Identity/Grades/Income; Renewal: Identity/
-- Grades/Enrollment. Receipt>=submission. Pending has NULL verification metadata;
-- Accepted/Rejected require verifier/date>=receipt. Rejected requires notes.
-- Renewal check: Renewal-only, externally verified prior award, units>=0,
-- GPA 1-5, date>=submission, staff, explained Ineligible result. Eligible requires
-- units>=minunits and GPA<=maxgpa plus valid previous-award applicability.
-- Evaluate only with ALL required categories Accepted, eligibility satisfied,
-- and evaluation date >= supporting document/check dates. Apply FirstAward
-- entry-average/income limits or require an Eligible renewal check.
-- Approval: noncancelled offering and available slot. Lock offering/recheck count
-- and commit atomically. Slots cannot be reduced below current approvals.
-- Closed intake can process earlier submissions; Cancelled blocks new submissions
-- and positive decisions but preserves evidence and explained outcomes.
-- Block threshold changes while Submitted/Evaluated applications depend on them.
-- Do not recalculate finalized results from later guidance. Protect model/identity
-- and date corrections against invalidating existing records and evidence.
-- Replacement resets document verification. Unsupported evaluations must be
-- cleared and application returned to Submitted atomically. Final states block
-- ordinary evidence/check changes. Controlled confirmed deletion preserves history.
-- Revision-checked saves increment after success and reject stale edits.
-- Keep one current college name per college code and agency name per agency code.
-- Staff names are attribution, not authentication. No user/audit table is assumed.
-- These rules remain required even though no CHECK clauses are generated.

START TRANSACTION;

-- applicant: 132 simulated records.

-- program: 8 simulated records.




-- offering: 34 simulated records.

-- application: 289 simulated records.

-- document: 810 simulated records.

-- renewcheck: 121 simulated records.

COMMIT;

-- VERIFICATION: adapted SQLite schema/INSERT load passed with PRIMARY KEY,
-- FOREIGN KEY, UNIQUE and NOT NULL intact. No CHECK or standalone index clauses.
-- Target MySQL execution has NOT been performed. Python separately inspected
-- dates, applicable values, eligibility, evaluation evidence, lengths and slots.
-- 2025 report-group counts remain 132, 34, 26 and 9. Zero-period applicants=23;
-- zero-period offerings=19. Six tables, 63 columns, 1,394 simulated records.
